{
  "name": "光谱仪校准EEPROM",
  "name_en": "Spectrometer Calibration EEPROM",
  "manufacturer": "Wasatch Photonics",
  "description": "这是集成在 Wasatch Photonics 光谱仪中的非易失性存储器，用于保存序列号、波长校准、探测器感兴趣区域、激光功率与探测器 TEC 校准、拉曼强度校准以及多波长配置等出厂参数。实验室中这些数据用于维持光谱仪的标定一致性、设备识别和测量配置，常见于拉曼及其他光谱测量系统。",
  "description_en": "This is a non-volatile memory component integrated into Wasatch Photonics spectrometers, used to store factory parameters such as serial number, wavelength calibration, detector ROI, laser power and detector TEC calibration, Raman intensity calibration, and multi-wavelength configuration. In laboratory use, this stored data supports instrument identification, calibration consistency, and measurement setup for Raman and other spectroscopy systems.",
  "tag_hints": [
    "spectrometer calibration",
    "Raman spectroscopy",
    "EEPROM memory",
    "wavelength calibration",
    "detector ROI",
    "laser power calibration",
    "TEC calibration",
    "multi-wavelength spectrometer"
  ],
  "actions": [
    {
      "action_name": "auto-init_fields",
      "description": "初始化EEPROM字段映射。",
      "description_en": "Initialize the EEPROM field mapping."
    },
    {
      "action_name": "auto-is_editable",
      "description": "检查指定存储字段是否允许编辑。",
      "description_en": "Check whether a stored field is editable."
    },
    {
      "action_name": "auto-update_editable",
      "description": "从另一份配置中更新可编辑的EEPROM字段。",
      "description_en": "Update editable EEPROM fields from another configuration copy."
    },
    {
      "action_name": "auto-parse",
      "description": "解析从光谱仪读取的EEPROM页缓冲区。",
      "description_en": "Parse EEPROM page buffers read from the spectrometer."
    },
    {
      "action_name": "auto-read_eeprom",
      "description": "读取并解码EEPROM中的已存参数。",
      "description_en": "Read and decode stored parameters from the EEPROM."
    },
    {
      "action_name": "auto-generate_feature_mask",
      "description": "生成EEPROM中的功能掩码标志。",
      "description_en": "Generate the feature-mask flags stored in EEPROM."
    },
    {
      "action_name": "auto-generate_write_buffers",
      "description": "生成写回EEPROM所需的页缓冲区。",
      "description_en": "Generate page buffers for writing back to EEPROM."
    },
    {
      "action_name": "auto-printable",
      "description": "将EEPROM字节数据转换为可打印文本。",
      "description_en": "Convert EEPROM byte data into printable text."
    },
    {
      "action_name": "auto-set",
      "description": "设定指定EEPROM字段的值。",
      "description_en": "Set the value of a specified EEPROM field."
    },
    {
      "action_name": "auto-float_to_uint16",
      "description": "将探测器增益值转换为EEPROM使用的16位格式。",
      "description_en": "Convert a detector gain value to the 16-bit format used in EEPROM."
    },
    {
      "action_name": "auto-unpack_field",
      "description": "解码指定名称的EEPROM字段。",
      "description_en": "Decode a named EEPROM field."
    },
    {
      "action_name": "auto-unpack",
      "description": "从指定页地址解码单个EEPROM值。",
      "description_en": "Decode a single EEPROM value from a specified page address."
    },
    {
      "action_name": "auto-pack_field",
      "description": "编码指定名称的EEPROM字段。",
      "description_en": "Encode a named EEPROM field."
    },
    {
      "action_name": "auto-pack",
      "description": "将单个值编码到指定EEPROM页地址。",
      "description_en": "Encode a single value to a specified EEPROM page address."
    },
    {
      "action_name": "auto-generate_digest",
      "description": "生成当前EEPROM内容的摘要。",
      "description_en": "Generate a digest of the current EEPROM contents."
    },
    {
      "action_name": "auto-to_dict",
      "description": "将EEPROM参数导出为字典结构。",
      "description_en": "Export EEPROM parameters as a dictionary structure."
    },
    {
      "action_name": "auto-json",
      "description": "将EEPROM参数导出为JSON字符串。",
      "description_en": "Export EEPROM parameters as a JSON string."
    },
    {
      "action_name": "auto-dump",
      "description": "输出EEPROM当前内容以供查看。",
      "description_en": "Dump the current EEPROM contents for inspection."
    },
    {
      "action_name": "auto-latest_rev",
      "description": "获取支持的最新EEPROM修订版本。",
      "description_en": "Get the latest supported EEPROM revision."
    },
    {
      "action_name": "auto-has_horizontal_roi",
      "description": "检查是否配置了水平ROI。",
      "description_en": "Check whether a horizontal ROI is configured."
    },
    {
      "action_name": "auto-has_laser_power_calibration",
      "description": "检查是否存在激光功率校准。",
      "description_en": "Check whether laser power calibration is present."
    },
    {
      "action_name": "auto-has_detector_tec_calibration",
      "description": "检查是否存在探测器TEC校准。",
      "description_en": "Check whether detector TEC calibration is present."
    },
    {
      "action_name": "auto-has_raman_intensity_calibration",
      "description": "检查是否存在拉曼强度校准。",
      "description_en": "Check whether Raman intensity calibration is present."
    },
    {
      "action_name": "auto-has_sml",
      "description": "检查是否配置了SML光源相关参数。",
      "description_en": "Check whether SML light-source configuration is present."
    },
    {
      "action_name": "auto-has_mml",
      "description": "检查是否配置了MML光源相关参数。",
      "description_en": "Check whether MML light-source configuration is present."
    },
    {
      "action_name": "auto-laser_power_mW_to_percent",
      "description": "依据已存校准将激光功率从毫瓦换算为百分比。",
      "description_en": "Convert laser power from milliwatts to percent using stored calibration."
    },
    {
      "action_name": "auto-is_valid_serial_number",
      "description": "检查存储的序列号是否有效。",
      "description_en": "Check whether the stored serial number is valid."
    },
    {
      "action_name": "auto-init_raman_intensity_calibration",
      "description": "初始化拉曼强度校准数据。",
      "description_en": "Initialize Raman intensity calibration data."
    },
    {
      "action_name": "auto-read_raman_intensity_calibration",
      "description": "读取拉曼强度校准数据。",
      "description_en": "Read Raman intensity calibration data."
    },
    {
      "action_name": "auto-write_raman_intensity_calibration",
      "description": "写入拉曼强度校准数据。",
      "description_en": "Write Raman intensity calibration data."
    },
    {
      "action_name": "auto-dump_raman_intensity_calibration",
      "description": "输出拉曼强度校准数据以供查看。",
      "description_en": "Dump Raman intensity calibration data for inspection."
    },
    {
      "action_name": "auto-init_spline",
      "description": "初始化样条校准数据。",
      "description_en": "Initialize spline calibration data."
    },
    {
      "action_name": "auto-read_spline",
      "description": "读取样条校准数据。",
      "description_en": "Read spline calibration data."
    },
    {
      "action_name": "auto-write_spline",
      "description": "写入样条校准数据。",
      "description_en": "Write spline calibration data."
    },
    {
      "action_name": "auto-dump_spline",
      "description": "输出样条校准数据以供查看。",
      "description_en": "Dump spline calibration data for inspection."
    },
    {
      "action_name": "auto-init_untethered",
      "description": "初始化脱机运行配置。",
      "description_en": "Initialize untethered operation settings."
    },
    {
      "action_name": "auto-read_untethered",
      "description": "读取脱机运行配置。",
      "description_en": "Read untethered operation settings."
    },
    {
      "action_name": "auto-write_untethered",
      "description": "写入脱机运行配置。",
      "description_en": "Write untethered operation settings."
    },
    {
      "action_name": "auto-dump_untethered",
      "description": "输出脱机运行配置以供查看。",
      "description_en": "Dump untethered operation settings for inspection."
    },
    {
      "action_name": "auto-get_horizontal_roi",
      "description": "获取水平ROI设置。",
      "description_en": "Get horizontal ROI."
    },
    {
      "action_name": "auto-is_multi_wavelength",
      "description": "检查是否启用了多波长校准配置。",
      "description_en": "Check whether multi-wavelength calibration is enabled."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化多波长校准结构。",
      "description_en": "Initialize the multi-wavelength calibration structure."
    },
    {
      "action_name": "auto-get",
      "description": "获取指定多波长校准属性。",
      "description_en": "Get a specified multi-wavelength calibration property."
    },
    {
      "action_name": "auto-read",
      "description": "读取多波长校准数据。",
      "description_en": "Read multi-wavelength calibration data."
    },
    {
      "action_name": "auto-write",
      "description": "写入多波长校准数据。",
      "description_en": "Write multi-wavelength calibration data."
    },
    {
      "action_name": "auto-toJSON",
      "description": "将多波长校准数据导出为JSON字符串。",
      "description_en": "Export multi-wavelength calibration data as a JSON string."
    }
  ]
}

